contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address caller, uint256 initialSupply, string memory tokenName, string memory tokenSymbol) public payable {
        require(caller != address(0), "caller must be nonzero");

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.owned(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        bool ownerIsCaller = (ownerBefore == address(this));
        bool expectedRevert = !ownerIsCaller;

        assert(reverted == expectedRevert && c.owner() == ownerBefore && c.totalSupply() == supplyBefore);
    }

    receive() external payable {}
}

