pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address caller, uint256 initialSupply, string memory tokenName, string memory tokenSymbol) internal {
        vm.assume(caller != address(0));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        uint256 supplyBefore;
        try c.totalSupply() returns (uint256 __r) { supplyBefore = __r; } catch { return; }
        bool reverted;
        try c.owned() { reverted = false; } catch { reverted = true; }
        bool ownerIsCaller = (ownerBefore == address(this));
        bool expectedRevert = !ownerIsCaller;
        assertTrue(reverted == expectedRevert && c.owner() == ownerBefore && c.totalSupply() == supplyBefore);
    }

